<script setup lang="ts">import {computed} from 'vue';interface Props{value?:number;max?:number;label?:string;showValue?:boolean;tone?:'primary'|'success'|'warning'|'danger'};const props=withDefaults(defineProps<Props>(),{value:0,max:100,label:'Progress',showValue:false,tone:'primary'});const percent=computed(()=>Math.min(100,Math.max(0,(props.value/Math.max(props.max,1))*100)))</script>
<template><div class="uv-progress" :class="`uv-progress--${tone}`"><div v-if="showValue" class="uv-progress__meta"><span>{{label}}</span><span>{{Math.round(percent)}}%</span></div><progress class="uv-progress__native" :value="value" :max="max" :aria-label="label">{{Math.round(percent)}}%</progress></div></template>
<style>.uv-progress{--_tone:var(--uv-color-primary,#2563eb);display:grid;gap:.45rem;width:100%;font-family:var(--uv-font-sans,system-ui,sans-serif)}.uv-progress--success{--_tone:var(--uv-color-success,#15803d)}.uv-progress--warning{--_tone:var(--uv-color-warning,#b45309)}.uv-progress--danger{--_tone:var(--uv-color-danger,#dc2626)}.uv-progress__meta{display:flex;justify-content:space-between;font-size:.8rem;color:var(--uv-color-text-muted,#64748b)}.uv-progress__native{width:100%;height:.65rem;appearance:none;border:0;border-radius:999px;overflow:hidden;background:var(--uv-color-disabled,#e2e8f0)}.uv-progress__native::-webkit-progress-bar{background:var(--uv-color-disabled,#e2e8f0)}.uv-progress__native::-webkit-progress-value{background:var(--_tone);border-radius:999px}.uv-progress__native::-moz-progress-bar{background:var(--_tone);border-radius:999px}</style>
